/* -------------------------
      HTML ELEMENTS
--------------------------*/
const navbar = document.getElementById("navbar");
const navToggle = document.getElementById("nav-toggle");
const navMenu = document.getElementById("nav-menu");
const navLinks = document.querySelectorAll(".nav-link");
const scrollTopBtn = document.getElementById("scroll-top");
const typingText = document.getElementById("typing-text");
const skillProgress = document.querySelectorAll(".skill-progress");
const contactForm = document.getElementById("contact-form");

/* -------------------------
      TYPING EFFECT TEXT
--------------------------*/
const typingPhrases = [
    "Java Developer",
    "GenAI Engineer",
    "Backend Developer",
    "Spring Boot Enthusiast",
    "Problem Solver"
];

let currentPhraseIndex = 0;
let currentCharIndex = 0;
let isDeleting = false;

function typeEffect() {
    const currentPhrase = typingPhrases[currentPhraseIndex];

    typingText.textContent = isDeleting
        ? currentPhrase.substring(0, currentCharIndex - 1)
        : currentPhrase.substring(0, currentCharIndex + 1);

    isDeleting ? currentCharIndex-- : currentCharIndex++;

    let speed = isDeleting ? 50 : 100;

    if (!isDeleting && currentCharIndex === currentPhrase.length) {
        speed = 2000;
        isDeleting = true;
    } else if (isDeleting && currentCharIndex === 0) {
        isDeleting = false;
        currentPhraseIndex = (currentPhraseIndex + 1) % typingPhrases.length;
        speed = 500;
    }

    setTimeout(typeEffect, speed);
}

/* -------------------------
      NAVIGATION
--------------------------*/
function toggleMobileNav() {
    navMenu.classList.toggle("active");
    navToggle.classList.toggle("active");
}

function closeMobileNav() {
    navMenu.classList.remove("active");
    navToggle.classList.remove("active");
}

function smoothScrollTo(targetId) {
    const el = document.querySelector(targetId);
    if (!el) return;

    const offsetTop = el.offsetTop - 80;

    window.scrollTo({
        top: offsetTop,
        behavior: "smooth",
    });
}

function updateActiveNavLink() {
    const sections = document.querySelectorAll("section[id]");
    const scrollPos = window.scrollY + 100;

    sections.forEach((section) => {
        const top = section.offsetTop;
        const height = section.offsetHeight;
        const id = section.getAttribute("id");

        if (scrollPos >= top && scrollPos < top + height) {
            navLinks.forEach((l) => {
                l.classList.remove("active");
                if (l.getAttribute("href") === `#${id}`) {
                    l.classList.add("active");
                }
            });
        }
    });
}

/* -------------------------
      SCROLL EVENTS
--------------------------*/
function handleNavbarScroll() {
    window.scrollY > 50
        ? navbar.classList.add("scrolled")
        : navbar.classList.remove("scrolled");
}

function handleScrollTopButton() {
    window.scrollY > 300
        ? scrollTopBtn.classList.add("visible")
        : scrollTopBtn.classList.remove("visible");
}

function animateSkillBars() {
    skillProgress.forEach((bar) => {
        const rect = bar.getBoundingClientRect();
        const visible = rect.top < window.innerHeight && rect.bottom > 0;

        if (visible && !bar.classList.contains("animated")) {
            const width = bar.getAttribute("data-width");
            bar.style.setProperty("--width", width);
            bar.classList.add("animated");
        }
    });
}

function animateCounters() {
    const counters = document.querySelectorAll(".stat-number");

    counters.forEach((counter) => {
        const rect = counter.getBoundingClientRect();
        const visible = rect.top < window.innerHeight && rect.bottom > 0;

        if (visible && !counter.classList.contains("animated")) {
            const target = parseFloat(counter.textContent);
            const increment = target / 100;
            let current = 0;

            const update = () => {
                current += increment;
                if (current < target) {
                    counter.textContent = current.toFixed(target % 1 === 0 ? 0 : 2);
                    requestAnimationFrame(update);
                } else {
                    counter.textContent = target.toString();
                }
            };

            counter.classList.add("animated");
            update();
        }
    });
}

/* -------------------------
     CONTACT FORM VALIDATION
--------------------------*/
function validateEmail(email) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function handleContactForm(e) {
    if (!contactForm) return;

    const fd = new FormData(contactForm);
    const name = fd.get("name")?.trim();
    const email = fd.get("email")?.trim();
    const subject = fd.get("subject")?.trim();
    const message = fd.get("message")?.trim();

    const inputs = contactForm.querySelectorAll("input, textarea");
    inputs.forEach((i) => (i.style.borderColor = "#eee"));

    let hasErrors = false;

    if (name.length < 2) {
        document.getElementById("name").style.borderColor = "#ff4757";
        hasErrors = true;
    }
    if (!validateEmail(email)) {
        document.getElementById("email").style.borderColor = "#ff4757";
        hasErrors = true;
    }
    if (subject.length < 5) {
        document.getElementById("subject").style.borderColor = "#ff4757";
        hasErrors = true;
    }
    if (message.length < 10) {
        document.getElementById("message").style.borderColor = "#ff4757";
        hasErrors = true;
    }

    if (hasErrors) {
        e.preventDefault();
        showNotification("Please fill in all fields correctly.", "error");
        return;
    }

    showNotification("Sending your message...", "success");
}

/* -------------------------
      NOTIFICATION SYSTEM
--------------------------*/
function showNotification(msg, type) {
    const old = document.querySelector(".notification");
    if (old) old.remove();

    const note = document.createElement("div");
    note.className = `notification ${type}`;

    note.innerHTML = `
        <i class="fas ${type === "success" ? "fa-check-circle" : "fa-exclamation-circle"}"></i>
        <span>${msg}</span>
        <button class="notification-close">&times;</button>
    `;

    Object.assign(note.style, {
        position: "fixed",
        top: "20px",
        right: "20px",
        background: type === "success" ? "#2ecc71" : "#e74c3c",
        padding: "15px 20px",
        borderRadius: "10px",
        color: "white",
        display: "flex",
        gap: "10px",
        alignItems: "center",
        zIndex: "9999",
        boxShadow: "0 10px 30px rgba(0,0,0,0.3)",
        transform: "translateX(300px)",
        transition: "0.3s ease",
    });

    document.body.appendChild(note);

    setTimeout(() => (note.style.transform = "translateX(0)"), 100);

    note.querySelector(".notification-close").onclick = () => {
        note.style.transform = "translateX(300px)";
        setTimeout(() => note.remove(), 300);
    };

    setTimeout(() => {
        if (note.parentNode) {
            note.style.transform = "translateX(300px)";
            setTimeout(() => note.remove(), 300);
        }
    }, 5000);
}

/* -------------------------
   INTERSECTION OBSERVER
--------------------------*/
function initIntersectionObserver() {
    const options = {
        threshold: 0.1,
        rootMargin: "0px 0px -50px 0px",
    };

    const observer = new IntersectionObserver((entries) => {
        entries.forEach((e) => {
            if (e.isIntersecting) e.target.classList.add("visible");
        });
    }, options);

    document.querySelectorAll(".fadeIn, .slideInLeft, .slideInRight").forEach((el) => observer.observe(el));
}

function addAnimationClasses() {
    document.querySelectorAll("section").forEach((s, i) => {
        s.classList.add(i % 2 === 0 ? "fadeIn" : "slideInLeft");
    });

    document.querySelectorAll(".project-card, .cert-item, .skill-item").forEach((c, i) => {
        c.classList.add(i % 2 === 0 ? "slideInLeft" : "slideInRight");
    });
}

/* -------------------------
      KONAMI CODE (Easter Egg)
--------------------------*/
let konamiCode = [];
const correctCode = [38, 38, 40, 40, 37, 39, 37, 39, 66, 65];

document.addEventListener("keydown", (e) => {
    konamiCode.push(e.keyCode);

    if (konamiCode.length > correctCode.length) {
        konamiCode.shift();
    }

    if (JSON.stringify(konamiCode) === JSON.stringify(correctCode)) {
        showNotification("🎉 Easter Egg Activated!", "success");

        const rainbowStyle = document.createElement("style");
        rainbowStyle.textContent = `
            @keyframes rainbow {
                0% { filter: hue-rotate(0deg); }
                100% { filter: hue-rotate(360deg); }
            }
        `;
        document.head.appendChild(rainbowStyle);

        document.body.style.animation = "rainbow 2s linear infinite";

        setTimeout(() => {
            document.body.style.animation = "";
            rainbowStyle.remove();
        }, 5000);

        konamiCode = [];
    }
});

/* -------------------------
       SCROLL HANDLER
--------------------------*/
const optimizedScrollHandler = debounce(() => {
    handleNavbarScroll();
    handleScrollTopButton();
    updateActiveNavLink();
    animateSkillBars();
    animateCounters();
}, 16);

/* -------------------------
         INIT
--------------------------*/
document.addEventListener("DOMContentLoaded", () => {
    addAnimationClasses();

    if (typingText) setTimeout(typeEffect, 800);

    if (navToggle) navToggle.addEventListener("click", toggleMobileNav);

    navLinks.forEach((link) => {
        link.addEventListener("click", (e) => {
            e.preventDefault();
            smoothScrollTo(link.getAttribute("href"));
            closeMobileNav();
        });
    });

    if (scrollTopBtn)
        scrollTopBtn.addEventListener("click", () => {
            window.scrollTo({ top: 0, behavior: "smooth" });
        });

    if (contactForm) contactForm.addEventListener("submit", handleContactForm);

    initIntersectionObserver();

    window.addEventListener("scroll", optimizedScrollHandler, { passive: true });
    window.addEventListener("resize", debounce(closeMobileNav, 250));
});

/* -------------------------
        HELPERS
--------------------------*/
function debounce(func, wait, immediate) {
    let timeout;

    return function () {
        const context = this,
            args = arguments;

        const later = function () {
            timeout = null;
            if (!immediate) func.apply(context, args);
        };

        const callNow = immediate && !timeout;

        clearTimeout(timeout);
        timeout = setTimeout(later, wait);

        if (callNow) func.apply(context, args);
    };
}
